const PAGE_SIZE = 8;
class ReportsComponent {
  // ── computed ─────────────────────────────────────────────────────────────────
  get assets() {
    const list = this.allAssets[this.activeDept] ?? [];
    const q = this.searchQuery.toLowerCase().trim();
    return list.filter(a => {
      const matchesSearch = !q || a.name.toLowerCase().includes(q);
      return matchesSearch;
    });
  }
  get pagedAssets() {
    const start = (this.currentPage - 1) * PAGE_SIZE;
    return this.assets.slice(start, start + PAGE_SIZE);
  }
  get totalPages() {
    return Math.max(1, Math.ceil(this.assets.length / PAGE_SIZE));
  }
  get pageNumbers() {
    return Array.from({
      length: this.totalPages
    }, (_, i) => i + 1);
  }
  get selectedCount() {
    return this.pagedAssets.filter(a => a.checked).length;
  }
  // summary totals for active dept
  get deptTotal() {
    return this.assets.reduce((s, a) => s + a.total, 0);
  }
  get deptReady() {
    return this.assets.reduce((s, a) => s + a.readyToDeploy, 0);
  }
  get deptDeployed() {
    return this.assets.reduce((s, a) => s + a.deployed, 0);
  }
  get deptDeadStock() {
    return this.assets.reduce((s, a) => s + a.deadStock, 0);
  }
  get deptUnderService() {
    return this.assets.reduce((s, a) => s + a.underService, 0);
  }
  get deptDamaged() {
    return this.assets.reduce((s, a) => s + a.damaged, 0);
  }
  constructor(router, assetService) {
    this.router = router;
    this.assetService = assetService;
    // ── state ────────────────────────────────────────────────────────────────────
    this.departments = [];
    this.activeDept = '';
    this.searchQuery = '';
    this.currentPage = 1;
    this.allChecked = false;
    this.sidebarOpen = false;
    this.isLoading = true;
    this.apiError = null;
    // ── filter ───────────────────────────────────────────────────────────────────
    this.filterOpen = false;
    this.filterTypes = [];
    // ── data (grouped by category) ───────────────────────────────────────────────
    this.allAssets = {};
  }
  ngOnInit() {
    this.loadReport();
  }
  ngOnDestroy() {}
  loadReport() {
    this.isLoading = true;
    this.apiError = null;
    this.assetService.getAssetStatusSummary().subscribe({
      next: response => {
        // Shape: { statusCode, type, responseData: { data: { assets: [] } } }
        const raw = response?.responseData?.data?.assets ?? [];
        // Group rows by category
        const grouped = {};
        raw.forEach((item, index) => {
          const cat = item.category ?? 'Other';
          if (!grouped[cat]) grouped[cat] = [];
          grouped[cat].push({
            id: item.assetTagName ?? `TAG-${index + 1}`,
            name: item.assetTagName ?? '—',
            category: cat,
            type: 'Asset',
            total: item.totalAssets ?? 0,
            readyToDeploy: item.ready ?? 0,
            deployed: item.deployed ?? 0,
            deadStock: item.deadStock ?? 0,
            underService: item.underMaintenance ?? 0,
            damaged: item.damaged ?? 0,
            checked: false
          });
        });
        this.allAssets = grouped;
        this.departments = Object.keys(grouped);
        this.activeDept = this.departments[0] ?? '';
        this.isLoading = false;
      },
      error: err => {
        console.error('Failed to load asset status summary:', err);
        this.apiError = 'Could not load report data from the server.';
        this.isLoading = false;
      }
    });
  }
  onDocumentClick() {
    this.sidebarOpen = false;
    this.filterOpen = false;
  }
  selectDept(dept) {
    this.activeDept = dept;
    this.currentPage = 1;
    this.allChecked = false;
  }
  toggleFilterPanel(event) {
    event.stopPropagation();
    this.filterOpen = !this.filterOpen;
  }
  clearFilters() {
    this.filterTypes = [];
    this.currentPage = 1;
  }
  exportCSV() {
